import { describe, expect, test } from "bun:test";
import { join } from "node:path";

import { extensionEntrySource, renderExtensionImports } from "./entry-source.ts";

const projectDir = "/tmp/example-project";
const transpiler = new Bun.Transpiler({ loader: "ts" });

describe("extensionEntrySource", () => {
	test("emits one absolute import per file, in the order given", () => {
		const source = extensionEntrySource({
			files: [join(projectDir, "extensions/clock.ts"), "extensions/ping.ts"],
			projectDir,
		});
		expect(source).toBe(
			[
				"// Generated by `crust build`. Edit nothing here.",
				`import extension0 from ${JSON.stringify("/tmp/example-project/extensions/clock.ts")};`,
				`import extension1 from ${JSON.stringify("/tmp/example-project/extensions/ping.ts")};`,
				"",
			].join("\n"),
		);
	});

	test("is empty for a project with no extensions", () => {
		expect(extensionEntrySource({ files: [], projectDir })).toBe("");
	});

	test("parses, and so does the whole fragment with its registry call", () => {
		const files = ["extensions/clock.ts", "extensions/ping.ts"];
		const imports = extensionEntrySource({ files, projectDir });
		expect(() => transpiler.transformSync(imports)).not.toThrow();
		expect(transpiler.transformSync(imports)).toContain("import");

		const module = [
			imports,
			"const registry = { register: (..._plugins: unknown[]) => {} };",
			renderExtensionImports(files),
			"",
		].join("\n");
		expect(() => transpiler.transformSync(module)).not.toThrow();
	});
});

describe("renderExtensionImports", () => {
	test("registers the same identifiers the imports declare, never their .default", () => {
		expect(renderExtensionImports(["a.ts", "b.ts"])).toBe(
			"registry.register(extension0, extension1);",
		);
		expect(renderExtensionImports(["a.ts"])).toBe("registry.register(extension0);");
	});

	test("is empty when there is nothing to register", () => {
		expect(renderExtensionImports([])).toBe("");
	});
});
